# Code generated by Claude
"""
Tests of the robot's face (src/face.py, FACE_CFG in src/robot_specs.py): visual only, hidden from the policy cameras, no effect on the physics fingerprint.

    MUJOCO_GL=egl python experiments/face_test.py [--out DIR] [--no-episodes]

Models are built one at a time (face off, a plain head for lack of images, the head with the face images) and compared:
1. The head: one ellipsoid in group 5 with no collision and no mass (every body mass and inertia equal to the model without it), a texture and a material for each
   image (none when an image is missing: a plain head and exactly one notice line, no error); the eagle camera sits outside the head and its forward ray hits nothing of it.
2. The physics: model_hash is the same with the face off, plain and textured; 300 physics steps give bit-identical states.
3. Hidden from the policy cameras: a probe camera (rendered by CameraRig, as every policy camera and inset is) looking at the face gives the same picture with and without
   the head; with the face group turned on, as the viewer does, the head shows, and the smile differs from the neutral face. Only the viewer and the composite view
   call show_face_group().
3c. Render-time turn of the head toward the view's camera (Face.facing): its front points at the camera for many camera poses, a proper rotation, upright, put back on exit,
   the state untouched; seen from behind, the smile shows on the turned head and not on the fixed one.
3b. The viewer's composite picture (follow view and camera tiles, shadows and reflections on, the third frame in a row) is the same with the face on and off apart from
   the head itself. Drawing the textured head made MuJoCo's renderer lose the shadows of the next render (the eagle tile, rendered first in the next frame) and of
   everything drawn after the head: the face material is 0.99 opaque (drawn late) and face.settle_renderer() takes the hit. Rendered in two processes, one GL
   context each.
4. A recording made with the face on verifies in replay (state hashes) with the face on, off, and plain (no GL needed).
5. (unless --no-episodes) The runner: a cheat episode (SUCCESS) shows the neutral face until the success, smiles from then on and runs 2 s more; the hold episode with
   stop_after_handoff_s = 2 ends 2 s after the handoff with the outcome STAGING_COMPLETE.
--out DIR writes the probe pictures (neutral and smile) there.
"""

import argparse
import contextlib
import io
import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import face, robot_specs  # noqa: E402
from src.cameras import CameraRig  # noqa: E402
from src.control_loop import _headless_context  # noqa: E402
from src.face import HEAD_GEOM, head_frame  # noqa: E402
from src.run_record import model_hash  # noqa: E402
from src.task_beaker_hotplate import load_task, run_beaker_episode  # noqa: E402
from src.replay import replay_run  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def probe_spec():
    """The probe camera: on the eagle camera's body (fixed to the torso), 45 cm in front of the face, looking at the head's centre."""
    eagle = next(cs for cs in robot_specs.CAMERA_SPECS if cs["name"] == "eagle_cam")
    centre, quat = head_frame(eagle)
    m = np.zeros(9)
    mujoco.mju_quat2Mat(m, quat)
    m = m.reshape(3, 3)
    front, up = -m[:, 0], m[:, 2]
    return {"name": "face_probe", "parent": eagle["parent"], "pos": list(centre + 0.45 * front), "look_at": list(centre), "up": list(up), "fovy": 30.0,
            "resolution": (320, 240), "shadows": False}


def build(mode):
    """Builds the beaker task's model with the face 'off', 'plain' (images missing) or 'textured'; returns (sim, notice lines printed)."""
    face.set_enabled(mode != "off")
    saved = robot_specs.FACE_CFG["image_dir"]
    if mode == "plain":
        robot_specs.FACE_CFG["image_dir"] = "assets/private/_no_such_folder"
    face._noticed.clear()
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf):
            sim = load_task(cameras=robot_specs.CAMERA_SPECS + [probe_spec()])
    finally:
        robot_specs.FACE_CFG["image_dir"] = saved
        face.set_enabled(None)
    return sim, [l for l in buf.getvalue().splitlines() if "face image" in l]


def render_probe(sim, option=None, smile=False):
    """Renders the probe camera with CameraRig (the policy cameras' renderer) and the given options (default: what every policy camera uses)."""
    gl, ctx = _headless_context(sim.model)
    try:
        rig = CameraRig(sim.model, [probe_spec()], ctx, shadows=False)
        if option is not None:
            rig.option = option
        sim.face.set_smile(smile)
        mujoco.mj_forward(sim.model, sim.data)
        rig.render(sim.data)
        return rig.images["face_probe"].copy()
    finally:
        gl.free()


def render_composite(mode, path):
    """Child process of check 3b: one frame of the viewer's composite layout with the face 'off' or 'on', saved as a PNG."""
    from src.viewer_composite import CompositeRenderer
    face.set_enabled(mode == "on")
    sim = load_task(cameras=True)
    m, d = sim.model, sim.data
    m.vis.global_.offwidth, m.vis.global_.offheight = max(m.vis.global_.offwidth, 960), max(m.vis.global_.offheight, 540)
    mujoco.mj_forward(m, d)
    gl, ctx = _headless_context(m)
    comp = CompositeRenderer(m, ctx, robot_specs.CAMERA_SPECS, size=(960, 540))
    for _ in range(3):                             # the third frame: the first render after the head was drawn used to lose its shadows (the eagle tile)
        img = comp.render(d, {"time": 0.0, "base_vel": (0, 0, 0), "twist": (0, 0), "status": None, "mode": "auto", "fps": 30.0}).copy()
    cv2.imwrite(path, cv2.cvtColor(img, cv2.COLOR_RGB2BGR))


def main(args):
    out = Path(args.out) if args.out else None
    info = {}
    imgs = {}
    for mode in ("off", "plain", "textured"):
        sim, notices = build(mode)
        m, d = sim.model, sim.data
        mujoco.mj_forward(m, d)
        info[mode] = {"hash": model_hash(m), "mass": m.body_mass.copy(), "inertia": m.body_inertia.copy(), "notices": notices, "present": sim.face.present,
                      "textured": sim.face.textured, "ngeom": m.ngeom}
        if mode != "off":
            g = sim.face.geom
            info[mode].update(contype=int(m.geom_contype[g]), conaffinity=int(m.geom_conaffinity[g]), group=int(m.geom_group[g]),
                              ntex=int(m.ntex), matids=[int(m.geom_matid[g])])
            cam = m.camera("eagle_cam").id
            R = d.geom_xmat[g].reshape(3, 3)
            local = R.T @ (d.cam_xpos[cam] - d.geom_xpos[g]) / np.array(robot_specs.FACE_CFG["head_radii"])
            info[mode]["cam_scaled_distance"] = float(np.linalg.norm(local))
            forward = -d.cam_xmat[cam].reshape(3, 3)[:, 2]
            gid = np.zeros(1, dtype=np.int32)
            hit = mujoco.mj_ray(m, d, d.cam_xpos[cam], forward, np.array([0, 0, 0, 0, 0, 1], np.uint8), 1, -1, gid)
            info[mode]["ray_hits_head"] = bool(hit >= 0)
        for _ in range(300):
            mujoco.mj_step(m, d)
        info[mode]["qpos"] = d.qpos.copy()
        mujoco.mj_resetData(m, d)
        mujoco.mj_forward(m, d)
        mujoco.mj_forward(m, d)
        imgs[(mode, "default")] = render_probe(sim)
        if mode == "textured":
            vopt = mujoco.MjvOption()
            face.show_face_group(vopt)
            imgs[("textured", "neutral")] = render_probe(sim, vopt, False)
            imgs[("textured", "smile")] = render_probe(sim, vopt, True)
            info[mode]["smiling_flag"] = sim.face.smiling
            info[mode]["matid_after_smile"] = int(m.geom_matid[sim.face.geom])
        del sim, m, d
    off, plain, tex = info["off"], info["plain"], info["textured"]

    print("\n1. the head")
    check("a head with no collision, in group 5", all(i["contype"] == 0 and i["conaffinity"] == 0 and i["group"] == 5 for i in (plain, tex)),
          f"contype {tex['contype']}, conaffinity {tex['conaffinity']}, group {tex['group']}")
    check("no mass: every body's mass and inertia equal to the model without the head", all(np.array_equal(off["mass"], i["mass"]) and np.array_equal(off["inertia"], i["inertia"])
                                                                                 for i in (plain, tex)))
    check("one more geom than without the head", plain["ngeom"] == off["ngeom"] + 1 and tex["ngeom"] == off["ngeom"] + 1, f"{off['ngeom']} -> {tex['ngeom']}")
    check("with the images: the face's textures and materials, both switchable", tex["present"] and tex["textured"] and tex["ntex"] >= 2)
    check("images missing: a plain head, exactly one notice line, no error", plain["present"] and not plain["textured"] and len(plain["notices"]) == 1, f"{plain['notices']}")
    check("the face off: no head", not off["present"])
    check("the eagle camera is outside the head (scaled distance > 1)", tex["cam_scaled_distance"] > 1.0, f"{tex['cam_scaled_distance']:.3f}")
    check("the camera's forward ray never meets the head", not tex["ray_hits_head"] and not plain["ray_hits_head"])

    print("\n2. the physics")
    check("model_hash is the same with the face off, plain and textured", off["hash"] == plain["hash"] == tex["hash"], f"{off['hash'][:12]} {plain['hash'][:12]} {tex['hash'][:12]}")
    check("300 physics steps: bit-identical states with and without the head", np.array_equal(off["qpos"], plain["qpos"]) and np.array_equal(off["qpos"], tex["qpos"]))

    print("\n3. hidden from the policy cameras")
    same = np.array_equal(imgs[("off", "default")], imgs[("textured", "default")]) and np.array_equal(imgs[("off", "default")], imgs[("plain", "default")])
    check("the probe camera (CameraRig, default groups) sees the same with and without the head", same,
          f"max pixel difference {int(np.abs(imgs[('off', 'default')].astype(int) - imgs[('textured', 'default')].astype(int)).max())}")
    shown = float(np.abs(imgs[("textured", "neutral")].astype(int) - imgs[("off", "default")].astype(int)).mean())
    check("with the face group on (the viewer) the head shows", shown > 5.0, f"mean pixel difference {shown:.1f}")
    smile = float(np.abs(imgs[("textured", "smile")].astype(int) - imgs[("textured", "neutral")].astype(int)).mean())
    check("the smile differs from the neutral face", smile > 1.0 and tex["smiling_flag"] and tex["matid_after_smile"] != tex["matids"][0], f"mean pixel difference {smile:.1f}")
    callers = sorted(p.name for p in (PROJECT_ROOT / "src").glob("*.py") if "show_face_group(" in p.read_text() and p.name != "face.py")
    check("only the viewer and the composite view draw the face group", callers == ["glfw_viewer.py", "viewer_composite.py"], f"{callers}")
    print("\n3c. the face turns to the view's camera (render time only)")
    sim, _ = build("textured")
    m, d = sim.model, sim.data
    mujoco.mj_forward(m, d)
    g = sim.face.geom
    rng = np.random.default_rng(0)
    worst_aim, worst_ortho, upright, restored, state_same = 1.0, 0.0, True, True, True
    for az, el in [(0, -15), (90, -15), (180, -15), (-90, -15), (45, -80), (200, 80)] + [(float(a), float(e)) for a, e in rng.uniform([-180, -85], [180, 85], (20, 2))]:
        cam = mujoco.MjvCamera()
        mujoco.mjv_defaultCamera(cam)
        cam.lookat[:] = d.geom_xpos[g] + rng.uniform(-0.3, 0.3, 3)
        cam.distance, cam.azimuth, cam.elevation = float(rng.uniform(0.5, 3.0)), az, el
        before, qpos, xpos = d.geom_xmat[g].copy(), d.qpos.copy(), d.xpos.copy()
        with sim.face.facing(d, cam):
            R = d.geom_xmat[g].reshape(3, 3)
            to_cam = face.free_camera_position(cam) - d.geom_xpos[g]
            worst_aim = min(worst_aim, float(np.dot(-R[:, 0], to_cam / np.linalg.norm(to_cam))))
            worst_ortho = max(worst_ortho, float(np.abs(R.T @ R - np.eye(3)).max()), abs(float(np.linalg.det(R)) - 1.0))
            upright &= bool(R[2, 2] > 0)
        restored &= bool(np.array_equal(before, d.geom_xmat[g]))
        state_same &= bool(np.array_equal(qpos, d.qpos) and np.array_equal(xpos, d.xpos))
    check("the head's front points at the camera for 26 camera poses (straight above and below too)", worst_aim > 1 - 1e-9, f"smallest cosine {worst_aim:.12f}")
    check("the orientation is a proper rotation and the head stays upright (local z up)", worst_ortho < 1e-9 and upright, f"max error {worst_ortho:.1e}")
    check("the head's matrix is put back on exit, and the state (qpos, body poses) is untouched", restored and state_same)
    gl, ctx = _headless_context(m)
    try:
        opt = mujoco.MjvOption()
        mujoco.mjv_defaultOption(opt)
        face.show_face_group(opt)
        scene = mujoco.MjvScene(m, maxgeom=10_000)
        cam = mujoco.MjvCamera()
        mujoco.mjv_defaultCamera(cam)
        yaw_behind = 0.0                                                   # the robot's heading is +x at the spawn: azimuth 0 looks along it, from behind
        cam.lookat[:] = d.geom_xpos[g]
        cam.distance, cam.elevation, cam.azimuth = 0.8, -15, yaw_behind

        def view(turned, smile):
            sim.face.set_smile(smile)
            if turned:
                with sim.face.facing(d, cam):
                    mujoco.mjv_updateScene(m, d, opt, None, cam, mujoco.mjtCatBit.mjCAT_ALL, scene)
            else:
                mujoco.mjv_updateScene(m, d, opt, None, cam, mujoco.mjtCatBit.mjCAT_ALL, scene)
            vp = mujoco.MjrRect(0, 0, 320, 240)
            mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_OFFSCREEN, ctx)
            mujoco.mjr_render(vp, scene, ctx)
            rgb = np.zeros((240, 320, 3), np.uint8)
            mujoco.mjr_readPixels(rgb, None, vp, ctx)
            mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_WINDOW, ctx)
            return rgb.astype(int)
        fixed = int((np.abs(view(False, True) - view(False, False)).sum(2) > 30).sum())
        turned = int((np.abs(view(True, True) - view(True, False)).sum(2) > 30).sum())
        sim.face.set_smile(False)
    finally:
        gl.free()
    check("seen from behind: the smile cannot be seen on the fixed head, and can on the turned head", fixed == 0 and turned > 200, f"pixels that differ, smile vs neutral: fixed {fixed}, turned {turned}")
    del sim, m, d

    if out:
        out.mkdir(parents=True, exist_ok=True)
        for k in ("neutral", "smile"):
            cv2.imwrite(str(out / f"face_{k}.png"), cv2.cvtColor(imgs[("textured", k)], cv2.COLOR_RGB2BGR))
        print(f"    probe pictures in {out}")

    import subprocess
    tmpc = Path(tempfile.mkdtemp(prefix="face_test_"))
    for mode in ("off", "on"):
        subprocess.run([sys.executable, str(Path(__file__).resolve()), "--_composite", mode, str(tmpc / f"{mode}.png")], check=True, capture_output=True)
    a, b = (cv2.imread(str(tmpc / f"{k}.png")).astype(int) for k in ("off", "on"))
    differ = int((np.abs(a - b).sum(2) > 30).sum())
    check("the composite picture is the same with the face on and off apart from the head (no lost shadows: floor, bench top and the eagle tile)", differ < 0.01 * a.shape[0] * a.shape[1],
          f"{differ} of {a.shape[0] * a.shape[1]} pixels differ; floor {a[300, 100].tolist()} / {b[300, 100].tolist()}, bench top {a[240, 480].tolist()} / {b[240, 480].tolist()}")
    tile_a, tile_b = a[420:540, 10:180], b[420:540, 10:180]
    check("the eagle tile in particular (the first camera rendered after the head)", np.abs(tile_a - tile_b).max() == 0, f"max pixel difference {int(np.abs(tile_a - tile_b).max())}")
    shutil.rmtree(tmpc, ignore_errors=True)

    print("\n4. replay verification with the face on, off and plain")
    tmp = Path(tempfile.mkdtemp(prefix="face_test_"))
    face.set_enabled(True)
    sim = load_task(cameras=True)                  # the recipe rebuilds the model with the standard cameras
    face.set_enabled(None)
    run_beaker_episode(None, sim.model, sim.data, out_dir=tmp / "ep", record_dir=tmp / "rec", loop_cfg={"bench_frames": 300}, face=sim.face)
    del sim
    for mode, flag in (("on", True), ("off", False)):
        rep = replay_run(tmp / "rec", video="none", quiet=True, face=flag)
        check(f"the recording verifies with the face {mode}", rep["ok"], f"{rep['ticks']} ticks, mismatch {rep['mismatch']}")
    robot_specs.FACE_CFG["image_dir"] = "assets/private/_no_such_folder"
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            rep = replay_run(tmp / "rec", video="none", quiet=True, face=True)
    finally:
        robot_specs.FACE_CFG["image_dir"] = "assets/private/face"
    check("the recording verifies with the images missing (plain head)", rep["ok"], f"{rep['ticks']} ticks, mismatch {rep['mismatch']}")
    shutil.rmtree(tmp, ignore_errors=True)

    if not args.no_episodes:
        print("\n5. the runner")
        from beaker_hotplate_episode import ARM_STAGES
        from src.task_beaker_hotplate import make_task
        from src.episode_runner import run_episode
        sim, _ = build("textured")
        tmp = Path(tempfile.mkdtemp(prefix="face_test_"))
        seen = []

        class Spy:
            """Wraps the Face to record when it is told to smile."""
            present = True

            def __init__(self, f):
                self.f = f

            def set_smile(self, on):
                seen.append(bool(on))
                self.f.set_smile(on)
        s = run_episode(make_task(ARM_STAGES["cheat"]), sim.model, sim.data, out_dir=tmp / "cheat", face=Spy(sim.face))
        check("cheat episode: SUCCESS", s["outcome"] == "SUCCESS", f"{s['outcome']}")
        check("neutral at the start, then smile once", seen == [False, True], f"{seen}")
        check("the episode ran 2 s after the success, with the smile showing", sim.face.smiling and 3.9 <= s["time_after_handoff_to_end"] <= 4.2,
              f"ended {s['time_after_handoff_to_end']:.2f} s after the handoff (the cheat teleports the beaker 2 s after it, then 2 s of smile)")
        s = run_episode(make_task(ARM_STAGES["hold"]), sim.model, sim.data, out_dir=tmp / "hold", face=sim.face, stop_after_handoff_s=2.0)
        check("hold episode with stop_after_handoff_s = 2: STAGING_COMPLETE 2 s after the handoff", s["outcome"] == "STAGING_COMPLETE"
              and abs(s["time_after_handoff_to_end"] - 2.0) < 0.05 and not sim.face.smiling, f"{s['outcome']}, {s['time_after_handoff_to_end']:.2f} s")
        shutil.rmtree(tmp, ignore_errors=True)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=None)
    ap.add_argument("--no-episodes", action="store_true")
    ap.add_argument("--_composite", nargs=2, metavar=("MODE", "PNG"), help=argparse.SUPPRESS)
    args = ap.parse_args()
    if args._composite:
        render_composite(*args._composite)
        sys.exit(0)
    sys.exit(0 if main(args) else 1)
